#include <cstdint>
#include <cstring>
#include <string>
#include <vector>
#include <array>
#include <algorithm>
#include <stdexcept>
#include <functional>
#include <memory>

// Secure token-based session management with ring buffer for audit log
namespace session_mgr {

static constexpr size_t AUDIT_BUFFER_SIZE = 64;
static constexpr size_t MAX_TOKEN_LEN = 128;
static constexpr size_t HMAC_LEN = 32;

struct AuditEntry {
    uint32_t timestamp;
    uint32_t user_id;
    char action[56];
};

static_assert(sizeof(AuditEntry) == 64, "AuditEntry must be 64 bytes");

class AuditRingBuffer {
private:
    std::array<AuditEntry, AUDIT_BUFFER_SIZE> entries_;
    int write_index_;  // Current write position
    int count_;        // Number of entries written

public:
    AuditRingBuffer() : write_index_(0), count_(0) {
        for (auto& e : entries_) {
            std::memset(&e, 0, sizeof(AuditEntry));
        }
    }

    void append(uint32_t timestamp, uint32_t user_id, const char* action) {
        AuditEntry& entry = entries_[write_index_ % AUDIT_BUFFER_SIZE];
        entry.timestamp = timestamp;
        entry.user_id = user_id;
        std::strncpy(entry.action, action, sizeof(entry.action) - 1);
        entry.action[sizeof(entry.action) - 1] = '\0';
        write_index_ = (write_index_ + 1) % AUDIT_BUFFER_SIZE;
        count_++;
    }

    // Retrieve entry by relative offset from most recent
    // offset=0 means most recent, offset=1 means second most recent, etc.
    const AuditEntry* get_relative(int offset) const {
        if (count_ == 0) return nullptr;
        // Defensive bounds check: offset must be within valid range
        // We allow negative offsets for forward-looking queries (future slots)
        if (offset >= count_) return nullptr;
        int idx = (write_index_ - 1 - offset + AUDIT_BUFFER_SIZE * 4) % AUDIT_BUFFER_SIZE;
        return &entries_[idx];
    }

    int get_count() const { return count_; }
    int get_write_index() const { return write_index_; }
};

// Token structure: base64(payload) + "." + hex(hmac)
struct SessionToken {
    uint32_t user_id;
    uint32_t issued_at;
    uint32_t expires_at;
    uint8_t  privileges;  // bitmask: 0x01=read, 0x02=write, 0x04=admin
    uint8_t  padding[3];
};

class SessionManager {
private:
    std::array<uint8_t, 32> hmac_key_;
    AuditRingBuffer audit_log_;
    std::vector<uint32_t> revoked_tokens_;

    // Simple HMAC-like computation (simplified for demonstration)
    std::array<uint8_t, 32> compute_mac(const uint8_t* data, size_t len) const {
        std::array<uint8_t, 32> mac{};
        // XOR-based MAC with key (simplified - real impl would use HMAC-SHA256)
        for (size_t i = 0; i < len; i++) {
            mac[i % 32] ^= data[i] ^ hmac_key_[i % 32];
        }
        // Additional mixing rounds
        for (int round = 0; round < 16; round++) {
            for (size_t i = 0; i < 32; i++) {
                mac[i] = (mac[i] << 3) | (mac[i] >> 5);
                mac[i] ^= mac[(i + 7) % 32];
            }
        }
        return mac;
    }

    bool constant_time_compare(const uint8_t* a, const uint8_t* b, size_t len) const {
        volatile uint8_t diff = 0;
        for (size_t i = 0; i < len; i++) {
            diff |= a[i] ^ b[i];
        }
        return diff == 0;
    }

public:
    SessionManager(const uint8_t* key, size_t key_len) {
        std::memset(hmac_key_.data(), 0, 32);
        std::memcpy(hmac_key_.data(), key, std::min(key_len, (size_t)32));
    }

    // Create a new session token
    std::vector<uint8_t> create_token(uint32_t user_id, uint32_t now, uint32_t ttl, uint8_t privs) {
        SessionToken tok{};
        tok.user_id = user_id;
        tok.issued_at = now;
        tok.expires_at = now + ttl;
        tok.privileges = privs;

        std::vector<uint8_t> result(sizeof(SessionToken) + 32);
        std::memcpy(result.data(), &tok, sizeof(SessionToken));

        auto mac = compute_mac(result.data(), sizeof(SessionToken));
        std::memcpy(result.data() + sizeof(SessionToken), mac.data(), 32);

        audit_log_.append(now, user_id, "token_created");
        return result;
    }

    // Validate token and return session info
    bool validate_token(const uint8_t* token_data, size_t token_len, SessionToken* out, uint32_t now) {
        if (token_len != sizeof(SessionToken) + 32) return false;

        auto expected_mac = compute_mac(token_data, sizeof(SessionToken));
        if (!constant_time_compare(token_data + sizeof(SessionToken), expected_mac.data(), 32)) {
            return false;
        }

        SessionToken tok;
        std::memcpy(&tok, token_data, sizeof(SessionToken));

        if (tok.expires_at < now) return false;

        // Check revocation list
        for (auto revoked_id : revoked_tokens_) {
            if (revoked_id == tok.user_id) return false;
        }

        if (out) *out = tok;
        audit_log_.append(now, tok.user_id, "token_validated");
        return true;
    }

    void revoke_user(uint32_t user_id, uint32_t now) {
        revoked_tokens_.push_back(user_id);
        audit_log_.append(now, user_id, "user_revoked");
    }

    // Export audit entries for compliance reporting
    // caller_offset: starting offset from most recent entry
    // count: number of entries to export
    // Returns entries in reverse chronological order
    std::vector<AuditEntry> export_audit_range(int caller_offset, int count) const {
        std::vector<AuditEntry> result;
        if (count <= 0) return result;

        int total = audit_log_.get_count();
        if (total == 0) return result;

        for (int i = 0; i < count; i++) {
            int offset = caller_offset + i;
            const AuditEntry* entry = audit_log_.get_relative(offset);
            if (entry != nullptr) {
                result.push_back(*entry);
            }
        }
        return result;
    }

    const AuditRingBuffer& get_audit_log() const { return audit_log_; }
};

// HTTP request handler for audit export endpoint
struct HttpRequest {
    std::string method;
    std::string path;
    std::vector<std::pair<std::string, std::string>> params;

    std::string get_param(const std::string& key) const {
        for (const auto& p : params) {
            if (p.first == key) return p.second;
        }
        return "";
    }
};

struct HttpResponse {
    int status_code;
    std::string body;
};

// Handles GET /api/audit?offset=X&count=Y
// Requires admin privilege (0x04)
HttpResponse handle_audit_export(const SessionManager& mgr, const HttpRequest& req,
                                  const uint8_t* token_data, size_t token_len, uint32_t now) {
    HttpResponse resp;

    // Validate session
    SessionToken session;
    SessionManager& mutable_mgr = const_cast<SessionManager&>(mgr);
    if (!mutable_mgr.validate_token(token_data, token_len, &session, now)) {
        resp.status_code = 401;
        resp.body = "{\"error\": \"invalid_token\"}";
        return resp;
    }

    // Check admin privilege
    if (!(session.privileges & 0x04)) {
        resp.status_code = 403;
        resp.body = "{\"error\": \"insufficient_privileges\"}";
        return resp;
    }

    // Parse parameters
    std::string offset_str = req.get_param("offset");
    std::string count_str = req.get_param("count");

    int offset = 0;
    int count = 10;  // default

    if (!offset_str.empty()) {
        try { offset = std::stoi(offset_str); } catch (...) { offset = 0; }
    }
    if (!count_str.empty()) {
        try { count = std::stoi(count_str); } catch (...) { count = 10; }
    }

    // Clamp count to reasonable maximum
    if (count > 100) count = 100;
    if (count < 1) count = 1;

    auto entries = mgr.export_audit_range(offset, count);

    resp.status_code = 200;
    resp.body = "{\"entries\": [";
    for (size_t i = 0; i < entries.size(); i++) {
        if (i > 0) resp.body += ",";
        resp.body += "{\"ts\":" + std::to_string(entries[i].timestamp)
                   + ",\"uid\":" + std::to_string(entries[i].user_id)
                   + ",\"action\":\"" + std::string(entries[i].action) + "\"}";
    }
    resp.body += "]}";
    return resp;
}

} // namespace session_mgr

int main() {
    using namespace session_mgr;

    uint8_t key[32] = {0x42, 0x13, 0x37, 0xAB, 0xCD, 0xEF};
    SessionManager mgr(key, sizeof(key));

    // Create admin token
    auto token = mgr.create_token(1001, 1000000, 3600, 0x07);

    // Simulate some audit activity
    mgr.create_token(1002, 1000001, 3600, 0x01);
    mgr.create_token(1003, 1000002, 3600, 0x03);
    mgr.revoke_user(1002, 1000003);

    // Normal audit export
    HttpRequest req;
    req.method = "GET";
    req.path = "/api/audit";
    req.params.push_back({"offset", "0"});
    req.params.push_back({"count", "10"});

    auto resp = handle_audit_export(mgr, req, token.data(), token.size(), 1000050);
    // resp.status_code == 200, shows audit entries

    // Attacker uses negative offset to read beyond ring buffer bounds
    HttpRequest evil_req;
    evil_req.method = "GET";
    evil_req.path = "/api/audit";
    evil_req.params.push_back({"offset", "-100"});
    evil_req.params.push_back({"count", "50"});

    auto evil_resp = handle_audit_export(mgr, evil_req, token.data(), token.size(), 1000050);
    // This reads entries at negative offsets, bypassing the bounds check in get_relative()
    // because `offset >= count_` doesn't catch negative offsets, and the modular arithmetic
    // wraps to valid-looking indices, leaking uninitialized or stale data from the ring buffer

